import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {isWebUrl,validateWebUrl} from './security.mjs';

const require=createRequire(import.meta.url);
let DatabaseSync=null;
try{({DatabaseSync}=require('node:sqlite'));}catch{/* Electron/Node without node:sqlite falls back to JSON scan. */}

export const TAO_SEARCH_VERSION='0.3.0-alpha.1';
export const SEARCH_INDEX_FORMAT='taowind.search.index.v0.1';

function stable(value){if(Array.isArray(value))return value.map(stable);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().map(k=>[k,stable(value[k])]));return value;}
function root(value){return createHash('sha256').update(JSON.stringify(stable(value))).digest('hex');}
function clean(value,max=200000){return String(value??'').replace(/\u0000/g,'').replace(/[\t\r ]+/g,' ').replace(/\n{3,}/g,'\n\n').trim().slice(0,max);}
function canonicalUrl(value){const u=new URL(validateWebUrl(value));u.hash='';return u.href;}
function hostOf(value){try{return new URL(value).hostname.toLowerCase();}catch{return '';}}
function now(){return new Date().toISOString();}
function cjkBigrams(text){const out=[];for(const run of String(text).match(/[\u3400-\u9fff\uf900-\ufaff]+/g)||[]){for(const ch of run)out.push(ch);for(let i=0;i<run.length-1;i++)out.push(run.slice(i,i+2));}return out;}
export function searchTokens(value){const text=String(value??'').normalize('NFKC').toLowerCase();const latin=text.match(/[\p{L}\p{N}_-]{2,}/gu)||[];return [...new Set([...latin,...cjkBigrams(text)].filter(Boolean))].slice(0,64);}
function termString(value){return searchTokens(value).join(' ');}
function matchQuery(query){const tokens=searchTokens(query).slice(0,24);if(!tokens.length)return '';return tokens.map(t=>'"'+t.replaceAll('"','""')+'"').join(' OR ');}
function sourcePriority(value){return ({crawler:5,'current-page':4,bookmark:3,history:2,manual:1}[value]||0);}
function recencyScore(iso){const ms=Date.now()-Date.parse(iso||0);if(!Number.isFinite(ms)||ms<0)return 0;const days=ms/86400000;return Math.max(0,2.2-(days/30)*2.2);}
function lexicalScore(row,query,tokens,bmNorm){const title=(row.title||'').normalize('NFKC').toLowerCase(),desc=(row.description||'').normalize('NFKC').toLowerCase(),url=(row.canonical_url||'').toLowerCase(),body=(row.content||'').normalize('NFKC').toLowerCase();const raw=String(query).normalize('NFKC').toLowerCase().trim();let score=bmNorm*6;const why=[];if(raw&&title.includes(raw)){score+=8;why.push('标题完整匹配');}let titleHits=0,bodyHits=0,urlHits=0;for(const t of tokens){if(title.includes(t))titleHits++;if(desc.includes(t)||body.includes(t))bodyHits++;if(url.includes(t))urlHits++;}if(titleHits){score+=Math.min(6,titleHits*1.5);why.push('标题关键词');}if(bodyHits){score+=Math.min(4,bodyHits*.65);why.push('正文相关');}if(urlHits){score+=Math.min(2.5,urlHits*.6);why.push('网址相关');}if(row.bookmarked){score+=2.6;why.push('已收藏');}if(row.visit_count>0){score+=Math.min(2.2,Math.log2(1+row.visit_count)*.6);why.push('曾访问');}const fresh=recencyScore(row.seen_at);if(fresh>.35){score+=fresh;why.push('近期');}if(row.protocol_native){score+=1.1;why.push('OPP/TINP 原生节点');}const q=Math.max(0,Math.min(10,Number(row.link_quality)||0));if(q>.15){score+=Math.min(2.5,q*.25);why.push('链接质量');}return {score,why:[...new Set(why)].slice(0,4)};}
function snippetFor(row,query){const text=clean(row.description||row.content||'',700);if(!text)return '';const q=String(query).trim().toLowerCase(),lower=text.toLowerCase();let i=q?lower.indexOf(q):-1;if(i<0){for(const t of searchTokens(query)){i=lower.indexOf(t.toLowerCase());if(i>=0)break;}}if(i<0)return text.slice(0,260)+(text.length>260?'…':'');const start=Math.max(0,i-90),end=Math.min(text.length,i+190);return (start?'…':'')+text.slice(start,end)+(end<text.length?'…':'');}

export class TaoSearchIndex{
  constructor(dir){this.dir=dir;fs.mkdirSync(dir,{recursive:true});this.dbFile=path.join(dir,'tao-search.sqlite');this.jsonFile=path.join(dir,'tao-search-fallback.json');this.backend='json';this.db=null;this.docs=[];if(DatabaseSync)try{this.db=new DatabaseSync(this.dbFile);this.#initDb();this.backend='sqlite-fts5';}catch(error){try{this.db?.close();}catch{}this.db=null;this.backend='json';this.warning='SQLite/FTS5 初始化失败，已退回本地扫描：'+error.message;}if(!this.db)this.#loadJson();}
  #initDb(){this.db.exec(`PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; CREATE TABLE IF NOT EXISTS pages(canonical_url TEXT PRIMARY KEY,url TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',host TEXT NOT NULL DEFAULT '',content_hash TEXT NOT NULL DEFAULT '',source_kind TEXT NOT NULL DEFAULT 'manual',indexed_at TEXT NOT NULL,seen_at TEXT NOT NULL,visit_count INTEGER NOT NULL DEFAULT 0,bookmarked INTEGER NOT NULL DEFAULT 0,protocol_native INTEGER NOT NULL DEFAULT 0,noindex INTEGER NOT NULL DEFAULT 0,link_quality REAL NOT NULL DEFAULT 0,evidence_root TEXT NOT NULL); CREATE VIRTUAL TABLE IF NOT EXISTS pages_fts USING fts5(canonical_url UNINDEXED,title_terms,body_terms,tokenize='unicode61 remove_diacritics 2'); CREATE TABLE IF NOT EXISTS receipts(receipt_root TEXT PRIMARY KEY,kind TEXT NOT NULL,url TEXT NOT NULL,created_at TEXT NOT NULL,payload TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_pages_seen ON pages(seen_at DESC); CREATE INDEX IF NOT EXISTS idx_pages_host ON pages(host);`);const cols=new Set(this.db.prepare('PRAGMA table_info(pages)').all().map(r=>r.name));if(!cols.has('link_quality'))this.db.exec('ALTER TABLE pages ADD COLUMN link_quality REAL NOT NULL DEFAULT 0');}
  #loadJson(){try{const parsed=JSON.parse(fs.readFileSync(this.jsonFile,'utf8'));if(parsed?.format===SEARCH_INDEX_FORMAT&&Array.isArray(parsed.docs))this.docs=parsed.docs;}catch{this.docs=[];}}
  #saveJson(){const tmp=this.jsonFile+'.tmp';fs.writeFileSync(tmp,JSON.stringify({format:SEARCH_INDEX_FORMAT,version:TAO_SEARCH_VERSION,docs:this.docs},null,2),{mode:0o600});fs.renameSync(tmp,this.jsonFile);}
  #recordReceipt(kind,url,payload){const body={format:'taowind.search.receipt.v0.1',kind,url,createdAt:now(),payload};const receipt={...body,receiptRoot:root(body)};if(this.db)this.db.prepare('INSERT OR REPLACE INTO receipts(receipt_root,kind,url,created_at,payload) VALUES(?,?,?,?,?)').run(receipt.receiptRoot,kind,url,receipt.createdAt,JSON.stringify(receipt));return receipt;}
  indexDocument(input={}){if(!isWebUrl(input.url))throw new Error('Tao Search 只能索引 HTTP/HTTPS 页面');const url=canonicalUrl(input.url);let declared=input.canonicalUrl&&isWebUrl(input.canonicalUrl)?canonicalUrl(input.canonicalUrl):url;try{if(new URL(declared).origin!==new URL(url).origin)declared=url;}catch{declared=url;}const canonical=declared;const existing=this.get(canonical)||{};const incomingContent=clean(input.content,200000);const content=incomingContent||existing.content||'';const title=clean(input.title||existing.title||canonical,500),description=clean(input.description||existing.description||'',2000);const source=sourcePriority(input.sourceKind)>=sourcePriority(existing.source_kind)?String(input.sourceKind||existing.source_kind||'manual'):existing.source_kind;const seen=String(input.seenAt||now()),indexed=String(input.indexedAt||now()),noindex=input.noindex===true?1:0;const data={canonical_url:canonical,url,title,description,content,host:hostOf(canonical),content_hash:root({title,description,content}),source_kind:source,indexed_at:indexed,seen_at:seen,visit_count:Math.max(0,Number(existing.visit_count||0)+(Number(input.visitDelta)||0)),bookmarked:input.bookmarked===undefined?Number(existing.bookmarked||0):Number(input.bookmarked===true),protocol_native:input.protocolNative===undefined?Number(existing.protocol_native||0):Number(input.protocolNative===true),noindex,link_quality:Math.max(0,Math.min(10,Number(input.qualityScore===undefined?existing.link_quality||0:input.qualityScore)||0))};const evidence={format:'taowind.search.index-record.v0.1',canonicalUrl:canonical,contentHash:data.content_hash,sourceKind:data.source_kind,indexedAt:indexed,noindex:!!noindex};data.evidence_root=root(evidence);if(this.db){this.db.prepare(`INSERT INTO pages(canonical_url,url,title,description,content,host,content_hash,source_kind,indexed_at,seen_at,visit_count,bookmarked,protocol_native,noindex,link_quality,evidence_root) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(canonical_url) DO UPDATE SET url=excluded.url,title=excluded.title,description=excluded.description,content=excluded.content,host=excluded.host,content_hash=excluded.content_hash,source_kind=excluded.source_kind,indexed_at=excluded.indexed_at,seen_at=excluded.seen_at,visit_count=excluded.visit_count,bookmarked=excluded.bookmarked,protocol_native=excluded.protocol_native,noindex=excluded.noindex,evidence_root=excluded.evidence_root`).run(data.canonical_url,data.url,data.title,data.description,data.content,data.host,data.content_hash,data.source_kind,data.indexed_at,data.seen_at,data.visit_count,data.bookmarked,data.protocol_native,data.noindex,data.link_quality,data.evidence_root);this.db.prepare('DELETE FROM pages_fts WHERE canonical_url=?').run(canonical);if(!noindex)this.db.prepare('INSERT INTO pages_fts(canonical_url,title_terms,body_terms) VALUES(?,?,?)').run(canonical,termString(title+' '+canonical),termString(description+' '+content));}else{const i=this.docs.findIndex(x=>x.canonical_url===canonical);if(i>=0)this.docs[i]=data;else this.docs.unshift(data);this.docs=this.docs.slice(0,25000);this.#saveJson();}const receipt=this.#recordReceipt('index',canonical,evidence);return {record:{...data},receipt};}
  get(canonical){if(!canonical)return null;if(this.db)return this.db.prepare('SELECT * FROM pages WHERE canonical_url=?').get(canonical)||null;return this.docs.find(x=>x.canonical_url===canonical)||null;}
  recordVisit(url,title='',extra={}){if(!isWebUrl(url))return null;return this.indexDocument({url,title,sourceKind:'history',visitDelta:1,protocolNative:extra.protocolNative===true,seenAt:extra.seenAt||now()});}
  setBookmarked(url,title,bookmarked=true){if(!isWebUrl(url))return null;return this.indexDocument({url,title,sourceKind:'bookmark',bookmarked,seenAt:now()});}
  search(query,{limit=20}={}){const q=clean(query,500),tokens=searchTokens(q);if(!q||!tokens.length)return [];let rows=[];if(this.db){const mq=matchQuery(q);if(!mq)return [];try{rows=this.db.prepare(`SELECT p.*,bm25(pages_fts,5.0,1.3) AS fts_score FROM pages_fts JOIN pages p USING(canonical_url) WHERE pages_fts MATCH ? AND p.noindex=0 LIMIT 100`).all(mq);}catch{rows=[];}}else rows=this.docs.filter(x=>!x.noindex&&tokens.some(t=>termString((x.title||'')+' '+(x.description||'')+' '+(x.content||'')+' '+x.canonical_url).includes(t))).slice(0,100);let maxBm=0;for(const r of rows)maxBm=Math.max(maxBm,Math.abs(Number(r.fts_score)||0));const scored=rows.map(r=>{const bmNorm=maxBm?Math.abs(Number(r.fts_score)||0)/maxBm:0;const s=lexicalScore(r,q,tokens,bmNorm);return {...r,relevance:s.score,why:s.why,snippet:snippetFor(r,q)};}).sort((a,b)=>b.relevance-a.relevance||String(b.seen_at).localeCompare(String(a.seen_at)));const diversified=[],hostCount=new Map();for(const row of scored){const n=hostCount.get(row.host)||0;if(n>=3&&diversified.length<Math.max(8,limit))continue;diversified.push(row);hostCount.set(row.host,n+1);if(diversified.length>=limit)break;}return diversified.map(({content,fts_score,...r})=>r);}
  stats(){if(this.db){const p=this.db.prepare('SELECT COUNT(*) pages,COUNT(DISTINCT host) hosts,SUM(CASE WHEN content<>\'\' THEN 1 ELSE 0 END) full_text,SUM(bookmarked) bookmarks FROM pages WHERE noindex=0').get();const receipts=this.db.prepare('SELECT COUNT(*) n FROM receipts').get();return {backend:this.backend,pages:Number(p.pages||0),hosts:Number(p.hosts||0),fullText:Number(p.full_text||0),bookmarks:Number(p.bookmarks||0),receipts:Number(receipts.n||0),warning:this.warning||''};}const visible=this.docs.filter(x=>!x.noindex);return {backend:this.backend,pages:visible.length,hosts:new Set(visible.map(x=>x.host)).size,fullText:visible.filter(x=>x.content).length,bookmarks:visible.filter(x=>x.bookmarked).length,receipts:0,warning:this.warning||''};}
  recentReceipts(limit=20){if(!this.db)return[];return this.db.prepare('SELECT payload FROM receipts ORDER BY created_at DESC LIMIT ?').all(Math.max(1,Math.min(100,limit))).map(r=>JSON.parse(r.payload));}
  clear(){if(this.db)this.db.exec('DELETE FROM pages;DELETE FROM pages_fts;DELETE FROM receipts;');else{this.docs=[];this.#saveJson();}return this.stats();}
  close(){try{this.db?.close();}catch{}}
}
